import http from "./httpClient.js";
import dashboardApi from "./dashboardApi.js";
import { useDashboardStore } from "@/store/dashboardStore.js";
import * as D from "@/utils/dashboardData";

// works even when dashboardData.js has not been updated yet
const ACTIVITY_PAGE = D.ACTIVITY_PAGE ?? 100;
const ACTIVITY_EXCLUDE_TYPES = D.ACTIVITY_EXCLUDE_TYPES ?? ["Person", "Security Context"];
const ASSIGNEE_FIELD = "ds6w:assignee"; // items assigned to the user (not owner / creator)

const SEARCH = "/federated/search";
const MAX_PAGES = 400; // safety stop per role
const LABEL_FIELDS = ["ds6w:label", "dcterms:title", "ds6w:identifier"];
const TYPE_FIELDS = ["ds6w:type", "ds6w:what/ds6w:type"];
const STATUS_FIELDS = ["ds6w:status", "ds6w:what/ds6w:status"];
// every field the table shows is requested explicitly; the index only returns what is asked for
const PROJECT = [
  "ds6w:where/ds6w:context/ds6w:usedInProject", "ds6w:where/ds6w:context/ds6w:project",
  "ds6w:where/ds6w:project", "ds6w:project",
];
const WANTED = [
  ...PROJECT,
  "ds6w:who/ds6w:originator", "ds6w:who/ds6w:lastModifiedBy", "ds6w:who/ds6w:responsible",
  "ds6w:what/ds6w:description", "ds6w:what/ds6w:revision", "ds6wg:what/ds6wg:revision",
  "resourceid", "ds6w:identifier", ...LABEL_FIELDS, ...TYPE_FIELDS, ...STATUS_FIELDS,
  "ds6w:what/ds6w:policy", "ds6w:policy", "ds6wg:revision", "ds6w:revision",
  "ds6w:where/ds6w:context/ds6w:project", "ds6w:project", "ds6w:description", "dcterms:description",
  "ds6w:responsible", "owner", "ds6w:assignee", "ds6w:who/ds6w:assignee", "ds6w:originator", "ds6w:lastModifiedBy",
  "ds6w:when/ds6w:created", "ds6w:created", "ds6w:when/ds6w:modified", "ds6w:modified",
];

const toArray = (v) => [].concat(v ?? []);
const first = (r, name) =>
  toArray((r.attributes || []).find((a) => a.name === name)?.value)[0] ?? "";
const firstOf = (r, names) => names.map((n) => String(first(r, n))).find(Boolean) || "";
// "In_Work" / "COMPLETE" -> "In Work" / "Complete"
const tidy = (v) => {
  const t = String(v || "").split(".").pop().replace(/_/g, " ").trim();
  if (!t) return "–";
  return t === t.toUpperCase() ? t.toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase()) : t;
};
const EXCLUDE = ` AND NOT (flattenedtaxonomies:(${ACTIVITY_EXCLUDE_TYPES.map((t) => `"types/${t}"`).join(" OR ")}))`;
const esc = (s) => String(s).replace(/"/g, '\\"');

// names the current user can appear under in the index
export function identityOf() {
  const u = useDashboardStore().getUser || {};
  const f = (u.firstName || "").trim();
  const l = (u.lastName || "").trim();
  const names = f && l ? [`${f} ${l}`, `${l} ${f}`, `${l}, ${f}`] : [];
  return [...new Set([...names, u.name, u.login].map((v) => (v || "").trim()).filter(Boolean))];
}

// one query per role: the server decides what "mine" means, so no name matching in the browser
function roleQuery(ids, field, sinceIso) {
  const who = ids.map((v) => `[${field}]:"${esc(v)}"`).join(" OR ");
  return sinceIso ? `(${who}) AND [ds6w:modified]>="${sinceIso}"` : `(${who})`;
}

const toRow = (r) => {
  const name = String(first(r, "ds6w:identifier"));
  const title = firstOf(r, LABEL_FIELDS) || String(r.label || r.title || "");
  return {
    id: String(first(r, "resourceid") || `${name}|${title}`),
    title,
    name,
    type: firstOf(r, TYPE_FIELDS) || "–",
    status: tidy(firstOf(r, STATUS_FIELDS)),
    policy: String(firstOf(r, ["ds6w:what/ds6w:policy", "ds6w:policy"])),
    revision: String(firstOf(r, ["ds6wg:revision", "ds6w:revision", "ds6w:what/ds6w:revision", "ds6wg:what/ds6wg:revision"])),
    project: String(firstOf(r, PROJECT)),
    description: String(firstOf(r, ["ds6w:description", "ds6w:what/ds6w:description", "dcterms:description"])),
    owner: String(firstOf(r, ["ds6w:responsible", "ds6w:who/ds6w:responsible", "owner"])),
    assignee: ["ds6w:assignee", "ds6w:who/ds6w:assignee"].map((n) => toArray((r.attributes || []).find((a) => a.name === n)?.value).join(", ")).find(Boolean) || "",
    originator: String(firstOf(r, ["ds6w:originator", "ds6w:who/ds6w:originator"])),
    lastModifiedBy: String(firstOf(r, ["ds6w:lastModifiedBy", "ds6w:who/ds6w:lastModifiedBy"])),
    created: firstOf(r, ["ds6w:when/ds6w:created", "ds6w:created"]),
    modified: firstOf(r, ["ds6w:when/ds6w:modified", "ds6w:modified"]),
    roles: [],
  };
};

// Pulls activity in chunks, newest first. loadMore(limit, onProgress) fetches up to `limit`
// more items per role (Infinity = everything) and calls onProgress({ loaded, target }).
// rows() returns every item loaded so far, deduplicated, with the roles the user has on it.
export function createActivityLoader(period) {
  const ids = identityOf();
  if (!ids.length) throw new Error("NO_USER");

  const since = period.days ? new Date(Date.now() - period.days * 86400000).toISOString() : null;
  const map = new Map();
  const roles = Object.entries({ owner: ASSIGNEE_FIELD }).map(([role, field]) => ({
    role,
    query: roleQuery(ids, field, since),
    next: null,
    started: false,
    sorted: true, // newest first; falls back to relevance if the index refuses the sort
    done: false,
    total: null, // exact count from the search
    fetched: 0,
    base: 0,
    pages: 0,
  }));

  async function post(r, p) {
    if (r.sorted) {
      p.order_field = "ds6w:modified";
      p.order_by = "desc";
    }
    try {
      return await http.post(SEARCH, p);
    } catch (e) {
      if (!r.sorted || r.started) throw e;
      r.sorted = false; // first call only: retry with the default order
      p.order_field = "relevance";
      return http.post(SEARCH, p);
    }
  }

  async function pull(r, limit, report) {
    while (!r.done && r.fetched - r.base < limit && r.pages < MAX_PAGES) {
      const p = dashboardApi.buildPayload("Task", {}, ACTIVITY_PAGE, r.next, r.query);
      p.query = r.query;
      p.refine = {}; // all object types
      p.source = ["3dspace"];
      p.specific_source_parameter = { "3dspace": { additional_query: EXCLUDE } };
      p.select_predicate = [
        ...new Set([...(p.select_predicate || []), ...WANTED]),
      ];
      if (!r.started) p.start = "0";

      const json = await post(r, p);
      const results = json.results || [];
      r.started = true;
      r.pages++;
      if (json.infos?.nmatches != null) r.total = json.infos.nmatches;

      if (!r.logged && results[0]) {
        r.logged = true; // lets you see which fields 3DEXPERIENCE returned for a blank column
        console.info("[activity] returned fields:", (results[0].attributes || []).map((a) => a.name));
      }
      results.forEach((res) => {
        const row = toRow(res);
        const have = map.get(row.id) || row;
        if (!have.roles.includes(r.role)) have.roles.push(r.role);
        map.set(row.id, have);
      });
      r.fetched += results.length;
      r.next = json.infos?.next_start;
      if (results.length < ACTIVITY_PAGE || !r.next) r.done = true;
      report();
    }
  }

  return {
    async loadMore(limit, onProgress) {
      roles.forEach((r) => (r.base = r.fetched));
      const report = () => {
        const known = roles.every((r) => r.total != null);
        onProgress?.({
          loaded: roles.reduce((n, r) => n + (r.fetched - r.base), 0),
          target: known
            ? roles.reduce((n, r) => n + Math.min(limit, Math.max(0, r.total - r.base)), 0)
            : 0,
        });
      };
      await Promise.all(roles.map((r) => pull(r, limit, report)));
    },
    rows: () => [...map.values()].map((r) => ({ ...r, roles: [...r.roles] })),
    totals: () => Object.fromEntries(roles.map((r) => [r.role, r.total])),
    hasMore: () => roles.some((r) => !r.done),
  };
}