import http from "./httpClient.js";
import dashboardApi from "./dashboardApi.js";
import { useDashboardStore } from "@/store/dashboardStore.js";
import { SCHEDULE_TYPES } from "@/utils/dashboardData";
import { applySchedule } from "@/utils/scheduleRules";

const SEARCH = "/federated/search";
const TYPE_KEY = "ds6w:what/ds6w:type";
const USED_IN_PROJECT = "ds6w:where/ds6w:context/ds6w:usedInProject";
const PAGE = 40;
const LIST_PAGE = 100; // page size when listing every task
const MAX_PAGES = 5000; // safety stop per search
const DETAIL_PARALLEL = 16; // detail calls in flight at once
const FLUSH_EVERY = 5; // rows handed to the UI per update
const LABEL_FIELDS = ["ds6w:label", "dcterms:title", "ds6w:identifier"];

const toArray = (v) => [].concat(v ?? []);
const attr = (r, name) =>
  toArray((r.attributes || []).find((a) => a.name === name)?.value);
const first = (r, name) => attr(r, name)[0] ?? "";
const labelOf = (r) =>
  LABEL_FIELDS.map((f) => String(first(r, f))).find(Boolean) ||
  String(r.label || r.title || r.name || "");

function baseCfg(type) {
  const e = useDashboardStore().getTypeConfig.find((t) => t.name === type);
  return {
    query: e?.query || "(3dexpprd:#all)",
    refine: e?.refineValue ? dashboardApi.refineOf(TYPE_KEY, e.refineValue) : {},
  };
}

// pages through a search; onPage(batch, json) hands each page over as it arrives; max stops early
async function searchAll(type, { query, refine, size = PAGE, predicates = [], source, onPage, max }) {
  const all = [];
  let next = null;
  for (let page = 0; page < MAX_PAGES; page++) {
    const p = dashboardApi.buildPayload(type, refine, size, next, query);
    p.query = query;
    p.refine = refine;
    p.select_predicate = [...new Set([...(p.select_predicate || []), ...predicates])];
    if (source) p.source = source;
    if (!next) p.start = "0";
    let json;
    try {
      json = await http.post(SEARCH, p);
    } catch (e) {
      if (!all.length) throw e;
      all.truncated = true; // the search refused to go deeper; keep what was read
      break;
    }
    const batch = json.results || [];
    all.push(...batch);
    onPage?.(batch, json);
    if (max && all.length >= max) return all.slice(0, max);
    next = json.infos?.next_start;
    if (batch.length < size || !next) break;
  }
  return all;
}

async function mapLimit(items, limit, fn) {
  const out = new Array(items.length);
  let i = 0;
  const worker = async () => {
    while (i < items.length) {
      const k = i++;
      out[k] = await fn(items[k]);
    }
  };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return out;
}

const WORK_OPTS = {
  predicates: [USED_IN_PROJECT, "resourceid", "ds6w:when/ds6w:modified", ...LABEL_FIELDS],
  source: ["3dspace", "swym"],
};

// all results of one work type (Task / Milestone / Phase / Gate) in one project
async function findByType(projectName, subType) {
  const typeRefine = dashboardApi.refineOf(TYPE_KEY, subType);
  const found = await searchAll("Task", {
    ...WORK_OPTS,
    query: baseCfg("Task").query,
    refine: { ...typeRefine, ...dashboardApi.refineOf(USED_IN_PROJECT, projectName) },
  });
  if (found.length) return found;

  // fallback: text search on the project name, keep exact matches only
  const q = `"${projectName.replace(/"/g, '\\"')}"`;
  const byText = await searchAll("Task", { ...WORK_OPTS, query: q, refine: typeRefine });
  return byText.filter((r) => attr(r, USED_IN_PROJECT).includes(projectName));
}

// estimatedDuration is read as days (calendar days); a milestone with 0 finishes on its start date
const durationDays = (v) => parseFloat(v);
function addDays(start, days) {
  const t = new Date(start);
  if (!start || isNaN(t) || !isFinite(days)) return undefined;
  t.setDate(t.getDate() + Math.max(0, Math.ceil(days) - 1));
  return t.toISOString();
}

// a row from a search result only (no dates yet)
const lightRow = (r, subType) => ({
  id: first(r, "resourceid"),
  title: labelOf(r),
  name: first(r, "ds6w:identifier"),
  objType: subType,
  project: String(first(r, USED_IN_PROJECT)),
  state: String(first(r, "ds6w:what/ds6w:status")).split(".").pop(),
  modified: String(first(r, "ds6w:when/ds6w:modified")),
  detailed: false,
});

async function fetchDetail(id) {
  try {
    return (await http.get(`/resources/v1/modeler/tasks/${id}`))?.data?.[0]?.dataelements || {};
  } catch (e) {
    return {}; // keep the row; its dates stay empty
  }
}

const withDates = (base, d) => ({
  ...base,
  detailed: true,
  state: d.state || base.state,
  estimatedStartDate: d.estimatedStartDate,
  estimatedFinishDate:
    d.estimatedFinishDate || addDays(d.estimatedStartDate, durationDays(d.estimatedDuration)),
  dueDate: d.dueDate,
  actualStartDate: d.actualStartDate,
  actualFinishDate: d.actualFinishDate,
});

// dates already read are kept in the browser, keyed by task id + last-modified, so the next visit
// shows every count at once and only changed tasks are read again
const CACHE_KEY = "schedule-dates-v1";
const DATE_KEYS = ["state", "estimatedStartDate", "estimatedFinishDate", "dueDate", "actualStartDate", "actualFinishDate"];
let cache = null;
const getCache = () => {
  if (cache) return cache;
  try {
    cache = JSON.parse(localStorage.getItem(CACHE_KEY) || "{}");
  } catch (e) {
    cache = {};
  }
  return cache;
};
let saveTimer = null;
const saveCache = () => {
  if (saveTimer) return; // at most one write every 2 s, also during a long scan
  saveTimer = setTimeout(() => {
    saveTimer = null;
    try {
      localStorage.setItem(CACHE_KEY, JSON.stringify(getCache()));
    } catch (e) {
      cache = {}; // storage full or unavailable: carry on without it
    }
  }, 2000);
};
const fromCache = (base) => {
  const c = base.modified && getCache()[base.id];
  return c && c.m === base.modified ? { ...base, detailed: true, ...c.d } : null;
};
const toCache = (row) => {
  if (!row.modified || !(row.estimatedStartDate || row.estimatedFinishDate || row.dueDate)) return; // a failed read is not kept
  getCache()[row.id] = { m: row.modified, d: Object.fromEntries(DATE_KEYS.map((k) => [k, row[k]])) };
  saveCache();
};

// loads the date details of the given rows; reports finished rows in groups of `flushEvery`
async function loadDetails(rows, onRows, flushEvery = FLUSH_EVERY) {
  const done = [];
  let buf = [];
  const flush = () => {
    if (buf.length) {
      onRows?.(buf);
      buf = [];
    }
  };
  await mapLimit(rows, DETAIL_PARALLEL, async (base) => {
    let row = fromCache(base);
    if (!row) {
      row = withDates(base, await fetchDetail(base.id));
      toCache(row);
    }
    done.push(row);
    buf.push(row);
    if (buf.length >= flushEvery) flush();
  });
  flush();
  saveCache();
  return done;
}

// ---- server-side counts and pages (needs date fields that the search index returns) ----
let F = null; // { start, finish, aStart, aFinish } short predicate names, set by probeSchedule
const pred = (n) => n.split("/").pop();
const DATE_NAMES = ["estimatedStartDate", "estimatedEndDate", "estimatedFinishDate", "actualStartDate", "actualEndDate", "actualFinishDate", "dueDate"];
const DATE_PREDICATES = DATE_NAMES.flatMap((n) => [`ds6w:when/ds6w:${n}`, `ds6w:${n}`]);
const FAR_PAST = "1970-01-01T00:00:00.000Z";
const dayStart = (offset = 0) => {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() + offset);
  return d.toISOString();
};

async function postSearch(type, query, size, start, order) {
  const p = dashboardApi.buildPayload("Task", dashboardApi.refineOf(TYPE_KEY, type), size, null, query);
  p.query = query;
  p.refine = dashboardApi.refineOf(TYPE_KEY, type);
  p.select_predicate = [...new Set([...(p.select_predicate || []), ...WORK_OPTS.predicates, ...DATE_PREDICATES])];
  p.source = WORK_OPTS.source;
  p.start = String(start);
  if (order) {
    p.order_field = order;
    p.order_by = "asc";
  }
  return http.post(SEARCH, p);
}

function filterQuery(filterId) {
  const base = baseCfg("Task").query;
  if (filterId === "all") return base;
  const notStarted = F.aStart ? ` AND NOT [${F.aStart}]>="${FAR_PAST}"` : "";
  const notDone = F.aFinish ? ` AND NOT [${F.aFinish}]>="${FAR_PAST}"` : ` AND NOT [ds6w:status]:"Complete"`;
  const end = F.finish;
  const t0 = dayStart(0);
  const rules = {
    overdue: `[${end}]<"${t0}"${notDone}`,
    lateStart: `[${F.start}]<"${t0}"${notStarted}${notDone}`,
    next7: `[${F.start}]>="${t0}" AND [${F.start}]<"${dayStart(8)}"${notStarted}`,
    next14: `[${F.start}]>="${t0}" AND [${F.start}]<"${dayStart(15)}"${notStarted}`,
  };
  return `${base} AND ${rules[filterId]}`;
}

export default {
  loadDetails,

  // finds which date fields the index returns; null = not available (use the per-row detail mode)
  async probeSchedule() {
    try {
      const json = await postSearch("Task", baseCfg("Task").query, 100, 0);
      const seen = new Set();
      (json.results || []).forEach((r) =>
        (r.attributes || []).forEach((a) => /date/i.test(a.name) && toArray(a.value).length && seen.add(a.name)),
      );
      console.info("[schedule] date fields returned by search:", [...seen]);
      console.info("[schedule] all fields of the first result:", (json.results?.[0]?.attributes || []).map((a) => a.name));
      const find = (re) => [...seen].find((n) => re.test(n));
      const f = {
        start: find(/estimatedStart/i),
        finish: find(/estimatedEnd|estimatedFinish/i) || find(/due/i),
        aStart: find(/actualStart/i),
        aFinish: find(/actualEnd|actualFinish/i),
      };
      if (!f.start || !f.finish) return false;
      F = Object.fromEntries(Object.entries(f).map(([k, v]) => [k, v && pred(v)]));
      await postSearch("Task", filterQuery("overdue"), 1, 0); // the date query must be accepted
      return true;
    } catch (e) {
      console.warn("[schedule] server-side counts unavailable:", e);
      F = null;
      return false;
    }
  },

  // matches per work type for one filter: [Task, Milestone, Phase, Gate] counts
  async countTypes(filterId) {
    return Promise.all(
      SCHEDULE_TYPES.map(async (t) => {
        const json = await postSearch(t, filterQuery(filterId), 1, 0);
        return json.infos?.nmatches ?? (json.results || []).length;
      }),
    );
  },

  // one page (offset-based) of a filter, spanning the work types in order; onRows(rows) gets the
  // rows without dates first and again with dates
  async pageOf(filterId, perType, page, size, onRows) {
    const from = (page - 1) * size;
    const to = from + size;
    let at = 0;
    const parts = [];
    SCHEDULE_TYPES.forEach((t, i) => {
      const lo = Math.max(from, at);
      const hi = Math.min(to, at + (perType[i] || 0));
      if (hi > lo) parts.push({ t, start: lo - at, n: hi - lo });
      at += perType[i] || 0;
    });
    const fetched = await Promise.all(
      parts.map(async ({ t, start, n }) => {
        const q = filterQuery(filterId);
        let json;
        try {
          json = await postSearch(t, q, n, start, filterId === "all" ? undefined : F.finish);
        } catch (e) {
          json = await postSearch(t, q, n, start);
        }
        return (json.results || []).map((r) => lightRow(r, t));
      }),
    );
    const light = fetched.flat();
    onRows?.(light);
    const full = await loadDetails(light, null, 1);
    const rows = full.map((r) => ({ ...r, days: applySchedule([r], filterId)[0]?.days ?? null }));
    const order = new Map(light.map((r, i) => [r.id, i]));
    return rows.sort((a, b) => order.get(a.id) - order.get(b.id));
  },

  // onNames(newNames) is called after every page; also returns the full sorted list
  async fetchProjects(onNames) {
    const seen = new Set();
    await searchAll("Project", {
      ...baseCfg("Project"),
      predicates: LABEL_FIELDS,
      onPage: (rows) => {
        const names = rows.map(labelOf).filter((n) => n && !seen.has(n) && seen.add(n));
        if (names.length) onNames?.(names);
      },
    });
    return [...seen].sort((a, b) => a.localeCompare(b));
  },

  // one project, with dates; onRows(rows) is called as results arrive
  async fetchTasks(projectName, onRows, onTotal) {
    const groups = await Promise.all(
      SCHEDULE_TYPES.map(async (t) => {
        const found = await findByType(projectName, t);
        onTotal?.(found.length); // known before the detail calls start
        return loadDetails(
          found.map((r) => lightRow(r, t)),
          onRows,
        );
      }),
    );
    return groups.flat();
  },

  // every project, WITHOUT dates (fast); dates are loaded per page with loadDetails.
  // onRows(rows) per page, onTotal(n) with the match count; returns { capped }
  async listAllTasks(onRows, onTotal) {
    let capped = false;
    await Promise.all(
      SCHEDULE_TYPES.map(async (t) => {
        let counted = false;
        const found = await searchAll("Task", {
          ...WORK_OPTS,
          size: LIST_PAGE,
          query: baseCfg("Task").query,
          refine: dashboardApi.refineOf(TYPE_KEY, t),
          onPage: (batch, json) => {
            if (!counted) {
              counted = true;
              onTotal?.(json.infos?.nmatches ?? batch.length);
            }
            onRows?.(batch.map((r) => lightRow(r, t)));
          },
        });
        if (found.truncated) capped = true; // only when the search itself stopped early
      }),
    );
    return { capped };
  },
};