<template>
  <v-app>
    <v-navigation-drawer permanent rail v-if="!['type', 'form', 'activity'].includes(screen)">
      <v-list nav density="compact">

        <v-list-item v-for="item in navList" :key="item.id" :prepend-icon="item.icon" :title="item.label"
          color="primary" :active="screen === item.id" @click="screen = item.id" />
      </v-list>
    </v-navigation-drawer>

    <v-main class="bg-grey-lighten-4 app-main">
      <div class="app-content">
      <TypeSelectionView v-if="screen === 'type'" @open-form="screen = 'form'" @open-activity="screen = 'activity'" @open-dashboard="onOpenDashboard"
        @open-saved-view="onOpenSavedView" />
        <MyActivityView v-else-if="screen === 'activity'" @go-home="screen = 'type'" />
        <CustomFormView v-else-if="screen === 'form'" @open-dashboard="onOpenDashboard" @go-home="screen = 'type'" />
        <DashboardView v-else-if="screen === 'dashboard'" :restore-view="pendingView" />
        <ScheduleView v-else-if="screen === 'schedule'" />
        <SavedViewsView v-else-if="screen === 'saved'" @open="onOpenSavedView" />
        <div v-else class="pa-8 text-center text-medium-emphasis">
          Coming soon
        </div>
      </div>
    </v-main>
    <AppToast />
  </v-app>
</template>

<script>
import TypeSelectionView from "@/views/TypeSelectionView.vue";
import DashboardView from "@/views/DashboardView.vue";
import AppToast from "@/components/common/AppToast.vue";
import { useDashboardStore } from "@/store/dashboardStore";
import MyActivityView from "@/views/MyActivityView.vue";
import CustomFormView from "@/views/CustomFormView.vue";
import ScheduleView from "@/views/ScheduleView.vue";
import SavedViewsView from "@/views/SavedViewsView.vue";
export default {
  name: "App",
  setup() {
    return { store: useDashboardStore() };
  },
  components: {
    TypeSelectionView,
    DashboardView,
    AppToast,
    CustomFormView,
    ScheduleView,
    SavedViewsView,
    MyActivityView
  },
  mounted() {
    const w = window.widget;
    w?.addPreference?.({ name: "extEmail", type: "text", label: "External email", defaultValue: "" });
    w?.addPreference?.({ name: "extPassword", type: "password", label: "External password", defaultValue: "" });
  },
  watch: {
    screen(newScreen) {
      if (newScreen === "type") {
        this.store.setCustomForm(null);
        this.store.setSource("3dx");
        this.widget?.setTitle("Attribute Driven Dashboard Widget");
      }
    },
  },
  props: {
    widget: { type: Object, default: null },
  },
  data() {
    return {
      pendingView: null,
      screen: "type",
      navItems: [
        { id: "type", icon: "mdi-home-outline", label: "Home" },
        { id: "dashboard", icon: "mdi-chart-line", label: "Dashboard" },
        { id: "schedule", icon: "mdi-calendar-clock-outline", label: "Project Schedule" },
        { id: "saved", icon: "mdi-bookmark-outline", label: "Saved Views" },
        { id: "info", icon: "mdi-information-outline", label: "Info" },
      ],
    };
  },

  computed: {
    currentYear() {
      return new Date().getFullYear();
    },
    navList() {
      return this.navItems.filter(
        (i) => i.id !== "schedule" || (this.store.type === "Project" && this.store.source !== "external"),
      );
    },
  },

  methods: {
    onOpenSavedView(view) {
      this.widget?.setTitle(view.name || "Saved View");
      this.pendingView = view;
      this.screen = "dashboard";
    },
    onOpenDashboard() {
      this.widget?.setTitle(this.store.type || "Dashboard");
      this.pendingView = null;
      this.screen = "dashboard";
    },
  },
};
</script>

<style lang="scss">
@use "@/assets/styles/dashboard.scss";
</style>

<style scoped>
.app-main {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.app-content {
  flex: 1;
}
</style>