<template>
  <div class="sa">
    <div class="sa-tiles">
      <button
        v-for="f in filters"
        :key="f.id"
        class="sa-tile"
        :class="{ on: filterId === f.id }"
        :style="{ '--c': f.color }"
        @click="filterId = f.id"
      >
        <span class="sa-icon"><v-icon :icon="f.icon" size="20" /></span>
        <span class="sa-body">
          <span class="sa-n">{{ counts[f.id] == null ? "…" : counts[f.id].toLocaleString() }}</span>
          <span class="sa-l">{{ f.short }}</span>
        </span>
      </button>
      <button class="sa-refresh" :disabled="loadingCounts" title="Reload" @click="loadCounts">
        <v-icon icon="mdi-refresh" size="18" :class="{ spin: loadingCounts }" />
      </button>
    </div>

    <div class="sa-panel">
      <div class="sa-summary">
        <span class="sa-dot" :style="{ background: current.color }" />
        <b>{{ (counts[filterId] ?? 0).toLocaleString() }}</b> {{ text.items }}
        <span class="sa-fname">{{ current.label }}</span>
        <span class="sa-fname">{{ text.pageNote }}</span>
      </div>

      <div v-if="loadingRows && !rows.length" class="sa-state">
        <v-progress-circular indeterminate size="28" width="3" color="primary" />
      </div>
      <div v-else-if="!rows.length" class="sa-state">{{ text.noItems }}</div>
      <template v-else>
        <div class="sa-table-wrap">
          <table class="sa-table">
            <thead>
              <tr>
                <th>{{ text.name }}</th>
                <th>{{ text.projectCol }}</th>
                <th>{{ text.type }}</th>
                <th>{{ text.state }}</th>
                <th v-for="c in dateColumns" :key="c.key">{{ c.label }}</th>
                <th class="r">{{ current.daysLabel }}</th>
              </tr>
            </thead>
            <tbody :class="{ busy: loadingRows }">
              <tr v-for="r in rows" :key="r.id">
                <td class="main">
                  <div class="name" :title="r.title">{{ r.title }}</div>
                  <div class="id">{{ r.name }}</div>
                </td>
                <td class="muted">{{ r.project || "–" }}</td>
                <td><span class="type">{{ r.objType }}</span></td>
                <td><span class="chip" :style="{ '--c': stateColor(r.state) }">{{ r.state || "–" }}</span></td>
                <td v-for="c in dateColumns" :key="c.key" class="muted">
                  {{ c.formatter(r[c.key]) || (r.detailed === false ? "…" : "–") }}
                </td>
                <td class="r">
                  <span v-if="r.days != null" class="badge" :style="{ '--c': current.color }">{{ r.days }} d</span>
                  <span v-else class="muted">–</span>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
        <div class="sa-pager">
          <span class="muted">{{ from }}–{{ to }} {{ text.of }} {{ (counts[filterId] || 0).toLocaleString() }}</span>
          <v-pagination v-model="page" :length="pages" :total-visible="5" density="comfortable" rounded="lg" />
        </div>
      </template>
    </div>
  </div>
</template>

<script>
import scheduleApi from "@/services/scheduleApi";
import {
  SCHEDULE_FILTERS,
  SCHEDULE_DATE_COLUMNS,
  SCHEDULE_STATE_COLORS,
  SCHEDULE_STATE_DEFAULT_COLOR,
} from "@/utils/dashboardData";
import { SCHEDULE_TEXT } from "@/utils/uiText";
import { toastBus } from "@/components/common/toastBus";

const SIZE = 10;
// "completed late" needs a comparison between two dates, which a search cannot count
const IDS = ["all", "overdue", "lateStart", "next7", "next14"];

export default {
  name: "ScheduleAllView",
  data() {
    return {
      text: SCHEDULE_TEXT,
      filters: SCHEDULE_FILTERS.filter((f) => IDS.includes(f.id)),
      dateColumns: SCHEDULE_DATE_COLUMNS,
      filterId: "all",
      perType: {}, // filter id -> counts per work type
      counts: {},
      page: 1,
      rows: [],
      loadingCounts: false,
      loadingRows: false,
      reqRows: 0,
    };
  },
  computed: {
    current() {
      return this.filters.find((f) => f.id === this.filterId);
    },
    pages() {
      return Math.max(1, Math.ceil((this.counts[this.filterId] || 0) / SIZE));
    },
    from() {
      return this.rows.length ? (this.page - 1) * SIZE + 1 : 0;
    },
    to() {
      return (this.page - 1) * SIZE + this.rows.length;
    },
  },
  watch: {
    filterId() {
      if (this.page === 1) this.loadRows();
      else this.page = 1;
    },
    page() {
      this.loadRows();
    },
  },
  mounted() {
    this.loadCounts();
  },
  methods: {
    stateColor(state) {
      return SCHEDULE_STATE_COLORS[String(state || "").toLowerCase()] || SCHEDULE_STATE_DEFAULT_COLOR;
    },
    async loadCounts() {
      this.loadingCounts = true;
      this.counts = {};
      this.perType = {};
      try {
        // the table's filter first, so the first page shows quickly
        const order = [this.filterId, ...IDS.filter((i) => i !== this.filterId)];
        await Promise.all(
          order.map(async (id) => {
            const per = await scheduleApi.countTypes(id);
            this.perType[id] = per;
            this.counts = { ...this.counts, [id]: per.reduce((a, b) => a + b, 0) };
            if (id === this.filterId) this.loadRows();
          }),
        );
      } catch (e) {
        console.error("[schedule] counts failed:", e);
        toastBus.emit(this.text.loadFailed, "error");
      } finally {
        this.loadingCounts = false;
      }
    },
    async loadRows() {
      const id = ++this.reqRows;
      const per = this.perType[this.filterId];
      if (!per) return;
      this.loadingRows = true;
      try {
        const rows = await scheduleApi.pageOf(this.filterId, per, this.page, SIZE, (light) => {
          if (id === this.reqRows) this.rows = light;
        });
        if (id === this.reqRows) this.rows = rows;
      } catch (e) {
        console.error("[schedule] page failed:", e);
        if (id === this.reqRows) toastBus.emit(this.text.loadFailed, "error");
      } finally {
        if (id === this.reqRows) this.loadingRows = false;
      }
    },
  },
};
</script>

<style scoped>
.sa-tiles { display: flex; gap: 12px; flex-wrap: wrap; align-items: stretch; margin-bottom: 16px; }
.sa-tile { --c: #0f62fe; display: flex; align-items: center; gap: 12px; min-width: 150px; flex: 1 1 150px; text-align: left; padding: 12px 14px; background: #fff; border: 1px solid #e8ecf2; border-left: 4px solid var(--c); border-radius: 10px; cursor: pointer; font-family: inherit; transition: box-shadow 0.15s ease, transform 0.15s ease; }
.sa-tile:hover { box-shadow: 0 4px 14px rgba(0, 0, 0, 0.08); transform: translateY(-1px); }
.sa-tile.on { background: color-mix(in srgb, var(--c) 6%, #fff); box-shadow: 0 0 0 1px var(--c); }
.sa-icon { display: flex; align-items: center; justify-content: center; width: 38px; height: 38px; border-radius: 10px; color: var(--c); background: color-mix(in srgb, var(--c) 12%, #fff); }
.sa-body { display: flex; flex-direction: column; }
.sa-n { font-size: 24px; font-weight: 700; line-height: 1.1; color: #1a1a1a; }
.sa-l { font-size: 12px; font-weight: 600; color: #555; }
.sa-refresh { align-self: center; width: 36px; height: 36px; border: 1px solid #e8ecf2; border-radius: 8px; background: #fff; cursor: pointer; color: #555; }
.spin { animation: sa-spin 0.9s linear infinite; }
@keyframes sa-spin { to { transform: rotate(360deg); } }
.sa-panel { background: #fff; border: 1px solid #e8ecf2; border-radius: 12px; padding: 16px 20px; box-shadow: 0 1px 3px rgba(16, 24, 40, 0.05); }
.sa-summary { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 13px; color: #333; margin-bottom: 12px; }
.sa-dot { width: 10px; height: 10px; border-radius: 50%; }
.sa-fname { color: #888; font-size: 12px; }
.sa-state { display: flex; justify-content: center; padding: 40px 0; color: #888; font-size: 13px; }
.sa-table-wrap { overflow-x: auto; }
.sa-table { width: 100%; border-collapse: collapse; font-size: 13px; min-width: 900px; }
.sa-table th { text-align: left; color: #888; font-weight: 600; font-size: 12px; padding: 8px 8px; border-bottom: 1px solid #eee; white-space: nowrap; }
.sa-table td { padding: 10px 8px; border-bottom: 1px solid #f3f4f6; color: #333; white-space: nowrap; }
.sa-table tbody.busy { opacity: 0.55; }
.r { text-align: right !important; }
.main .name { font-weight: 600; max-width: 260px; overflow: hidden; text-overflow: ellipsis; }
.main .id { font-size: 11px; color: #888; }
.muted { color: #777; }
.type { background: #f0f2f5; border-radius: 6px; padding: 2px 8px; font-size: 12px; }
.chip { --c: #6f6f6f; color: var(--c); background: color-mix(in srgb, var(--c) 12%, #fff); border-radius: 999px; padding: 2px 10px; font-size: 12px; font-weight: 600; }
.badge { --c: #da1e28; color: var(--c); background: color-mix(in srgb, var(--c) 12%, #fff); border-radius: 6px; padding: 2px 8px; font-size: 12px; font-weight: 600; }
.sa-pager { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 12px; flex-wrap: wrap; font-size: 12px; }
</style>