<template>
  <div class="drill-panel">
    <div class="drill-head">
      <div class="drill-title">{{ text.drillTitle }}</div>
      <div class="drill-chip">
        {{ label }}
        <v-icon icon="mdi-close" size="14" title="Remove filter" @click="$emit('close')" />
      </div>
      <v-icon icon="mdi-close" size="18" title="Close" class="drill-close" @click="$emit('close')" />
    </div>

    <div class="drill-count">{{ shown.length.toLocaleString() }} {{ text.itemsSuffix }}<span v-if="note" class="drill-note"> · {{ note }}</span></div>
    <div class="drill-table-wrap">
      <table class="drill-table">
        <thead>
          <tr>
            <th v-for="c in columns" :key="c.key">
              <div class="th-label">{{ c.label }}</div>
              <input v-model="filters[c.key]" :placeholder="text.filterPlaceholder" autocomplete="off" />
            </th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="r in pageRows" :key="r.id">
            <td v-for="c in columns" :key="c.key" :class="c.cls" :title="c.key === 'description' ? r.description : ''">
              {{ cellText(r, c.key) }}
            </td>
          </tr>
          <tr v-if="!shown.length">
            <td :colspan="columns.length" class="drill-empty">{{ text.drillEmpty }}</td>
          </tr>
        </tbody>
      </table>
    </div>

    <div class="pager">
      <v-icon icon="mdi-chevron-left" size="16" title="Previous page" @click="page = Math.max(1, page - 1)" />
      <span>{{ text.pagePrefix }} {{ page }} {{ text.of }} {{ totalPages }}</span>
      <v-icon icon="mdi-chevron-right" size="16" title="Next page" @click="page = Math.min(totalPages, page + 1)" />
    </div>
  </div>
</template>

<script>
import { formatDate } from "@/utils/dashboardData";
import { ACTIVITY_TEXT as UI_TEXT } from "@/utils/uiText";

const ACTIVITY_TEXT = { itemsSuffix: "items", ...UI_TEXT };

const PAGE = 25;
const COLUMNS = [
  { key: "title", label: "Title", cls: "c-title" },
  { key: "name", label: "Name" },
  { key: "type", label: "Type" },
  { key: "status", label: "State" },
    { key: "assignee", label: "Assigned To" },
  { key: "owner", label: "Owner" },
  { key: "originator", label: "Originator" },
  { key: "lastModifiedBy", label: "Modified By" },
  { key: "created", label: "Created" },
  { key: "modified", label: "Modified" },
  { key: "policy", label: "Policy" },
  { key: "revision", label: "Revision" },
  { key: "project", label: "Project" },
  { key: "description", label: "Description", cls: "c-desc" },
];

export default {
  name: "ActivityDrillPanel",
  props: {
    label: { type: String, default: "" },
    note: { type: String, default: "" },
    rows: { type: Array, default: () => [] },
  },
  emits: ["close"],
  data() {
    return {
      text: ACTIVITY_TEXT,
      page: 1,
      columns: COLUMNS,
      filters: Object.fromEntries(COLUMNS.map((c) => [c.key, ""])),
    };
  },
  computed: {
    roleById() {
      return {};
    },
    shown() {
      const active = this.columns.filter((c) => this.filters[c.key].trim());
      if (!active.length) return this.rows;
      return this.rows.filter((r) =>
        active.every((c) => this.cellText(r, c.key).toLowerCase().includes(this.filters[c.key].trim().toLowerCase())),
      );
    },
    totalPages() {
      return Math.max(1, Math.ceil(this.shown.length / PAGE));
    },
    pageRows() {
      return this.shown.slice((this.page - 1) * PAGE, this.page * PAGE);
    },
  },
  watch: {
    shown() {
      if (this.page > this.totalPages) this.page = 1;
    },
    label() {
      this.page = 1; // new chart clicked
    },
  },
  methods: {
    cellText(r, key) {
      if (key === "created" || key === "modified") return formatDate(r[key]) || "–";
      return String(r[key] || "–");
    },
  },
};
</script>

<style scoped>
.drill-panel { width: 800px; max-width: 100%; height: calc(100vh - 70px); flex-shrink: 0; background: #fff; border: 1px solid #eee; border-radius: 10px; padding: 16px; box-sizing: border-box; display: flex; flex-direction: column; overflow: hidden; }
.drill-head { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; flex-shrink: 0; }
.drill-close { margin-left: auto; }
.drill-head .v-icon, .drill-chip .v-icon, .pager .v-icon { cursor: pointer; }
.drill-title { font-size: 13px; font-weight: 600; color: #0f62fe; flex-shrink: 0; }
.drill-chip { display: inline-flex; align-items: center; gap: 6px; background: #e8f0fe; color: #0f62fe; font-size: 12px; padding: 4px 10px; border-radius: 6px; flex-shrink: 0; }
.drill-count { font-size: 12px; color: #666; margin-bottom: 8px; flex-shrink: 0; }
.drill-note { color: #b26a00; }
.drill-table-wrap { flex: 1; min-height: 0; overflow: auto; }
.drill-table { width: 100%; border-collapse: collapse; font-size: 12px; min-width: 1500px; font-family: inherit; }
.drill-table th { position: sticky; top: 0; z-index: 2; background: #fff; text-align: left; color: #888; font-weight: 600; padding: 6px 4px; border-bottom: 1px solid #eee; white-space: nowrap; vertical-align: top; }
.th-label { margin-bottom: 4px; }
.drill-table th input { width: 100%; min-width: 90px; box-sizing: border-box; font-family: inherit; font-size: 11px; padding: 4px 6px; border: 1px solid #ddd; border-radius: 4px; font-weight: normal; color: #333; }
.drill-table td { padding: 6px 4px; border-bottom: 1px solid #f5f5f5; color: #333; white-space: nowrap; }
.c-title { font-weight: 600; max-width: 220px; overflow: hidden; text-overflow: ellipsis; }
.c-desc { max-width: 240px; overflow: hidden; text-overflow: ellipsis; }
.role { --c: #0f62fe; display: inline-block; margin-right: 4px; font-size: 11px; font-weight: 600; color: var(--c); background: color-mix(in srgb, var(--c) 12%, #fff); border-radius: 6px; padding: 2px 6px; }
.drill-empty { text-align: center; color: #999; padding: 16px 4px; }
.pager { display: flex; align-items: center; justify-content: center; gap: 10px; font-size: 12px; margin-top: 10px; color: #666; flex-shrink: 0; }
@media (max-width: 900px) { .drill-panel { position: fixed; inset: 0; width: 100%; max-height: 100%; z-index: 20; border-radius: 0; } }
.drill-table-wrap::-webkit-scrollbar { width: 8px; height: 8px; }
.drill-table-wrap::-webkit-scrollbar-thumb { background: #c7c7c7; border-radius: 4px; }
.drill-table-wrap::-webkit-scrollbar-thumb:hover { background: #999; }
</style>