// src/plugins/vuetify.js

import 'vuetify/styles'
import '@mdi/font/css/materialdesignicons.css'

import { createVuetify } from 'vuetify'
import * as components from 'vuetify/components'
import * as directives from 'vuetify/directives'

const vuetify = createVuetify({
  components,
  directives,

  icons: {
    defaultSet: 'mdi'
  },

  theme: {
    defaultTheme: 'dashboardTheme',

    themes: {
      dashboardTheme: {
        dark: false,
        colors: {
          primary: '#0F62FE',
          secondary: '#6B7280',
          background: '#F5F7FA',
          surface: '#FFFFFF',
          success: '#198754',
          warning: '#F59E0B',
          error: '#DC3545'
        }
      }
    }
  },

  defaults: {
    VCard: {
      elevation: 2,
      rounded: 'xl'
    },
    VBtn: {
      rounded: 'lg',
      height: 44
    },
    VTextField: {
      variant: 'outlined',
      density: 'comfortable'
    },
    VSelect: {
      variant: 'outlined',
      density: 'comfortable'
    }
  }
})

export default vuetify