<template>
  <div class="sv-wrap">
    <div class="sv-card">
      <!-- Header -->
      <div class="sv-head">
        <div>
          <div class="sv-title">Saved Views</div>
          <div class="sv-sub">Manage and organize your dashboard views</div>
        </div>

        <div class="sv-head-actions">
          <v-btn
            icon
            variant="text"
            class="refresh-btn"
            @click="loadSavedViews"
          >
            <v-icon>mdi-refresh</v-icon>
          </v-btn>
        </div>
      </div>

      <!-- Filters -->
      <div class="toolbar">
        <div class="toolbar-left">
          <v-select
            v-model="typeFilter"
            :items="typeOptions"
            label="Type"
            density="comfortable"
            variant="outlined"
            hide-details
            clearable
            class="filter-select"
          />

          <v-select
            v-model="createdByFilter"
            :items="createdByOptions"
            label="Created By"
            density="comfortable"
            variant="outlined"
            hide-details
            clearable
            class="filter-select"
          />
        </div>
      </div>

      <!-- Table -->
      <div class="table-wrapper">
        <table class="saved-table">
          <thead>
            <tr>
              <th width="22%">View Name</th>

              <th width="12%">Type</th>

              <th>Description</th>

              <th width="12%">Created On</th>

              <th width="12%">Modified</th>

              <th width="12%">Created By</th>

              <th width="110"></th>
            </tr>
          </thead>

          <tbody>
            <tr v-for="view in filteredViews" :key="view.id" class="table-row">
              <!-- Name -->
              <td>
                <div class="view-name" @click="$emit('open', view)">
                  {{ view.name }}
                </div>
              </td>

              <!-- Type -->
              <td>
                <span class="type-chip">
                  {{ view.type }}
                </span>
              </td>

              <!-- Description -->
              <td>
                <div class="description" :title="view.desc || view.description">
                  {{ view.desc || view.description || "-" }}
                </div>
              </td>

              <!-- Created -->
              <td>
                {{ view.createdOn }}
              </td>

              <!-- Modified -->
              <td>
                {{ view.modifiedOn }}
              </td>

              <!-- User -->
              <td>
                <div class="creator">
                  <div class="avatar">
                    {{ (view.createdBy || "U").charAt(0).toUpperCase() }}
                  </div>

                  <span>
                    {{ view.createdBy }}
                  </span>
                </div>
              </td>

              <!-- Actions -->
              <td>
                <div v-if="canModify(view)" class="action-buttons">
                  <v-tooltip bottom>
                    <template v-slot:activator="{ on, attrs }">
                      <v-btn
                        icon
                        small
                        v-bind="attrs"
                        v-on="on"
                        @click="editItem(view)"
                      >
                        <v-icon small>mdi-pencil-outline</v-icon>
                      </v-btn>
                    </template>
                    <span>Edit</span>
                  </v-tooltip>

                  <v-tooltip text="Duplicate">
                    <template #activator="{ props }">
                      <v-btn
                        v-bind="props"
                        icon
                        size="small"
                        variant="text"
                        @click="duplicateItem(view)"
                      >
                        <v-icon size="18"> mdi-content-copy </v-icon>
                      </v-btn>
                    </template>
                  </v-tooltip>

                  <v-tooltip text="Delete">
                    <template #activator="{ props }">
                      <v-btn
                        v-bind="props"
                        icon
                        size="small"
                        variant="text"
                        @click="deleteItem(view)"
                      >
                        <v-icon size="18" color="error">
                          mdi-delete-outline
                        </v-icon>
                      </v-btn>
                    </template>
                  </v-tooltip>
                </div>
              </td>
            </tr>

            <tr v-if="filteredViews.length === 0">
              <td colspan="7" class="empty-state">
                <v-icon size="42" color="grey">
                  mdi-folder-open-outline
                </v-icon>

                <div class="mt-2">No Saved Views Found</div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>

    <SaveViewDialog v-model="dialog" :edit-view="editing" @save="handleSave" />
  </div>
</template>

<script>
import SaveViewDialog from "@/components/dashboard/SaveViewDialog.vue";
import savedViewsApi from "@/services/savedViewsApi";
import { DEFAULT_TYPE } from "@/utils/dashboardData";
import { useDashboardStore } from "@/store/dashboardStore.js";
import { toastBus } from "@/components/common/toastBus";

export default {
  name: "SavedViewsView",

  components: {
    SaveViewDialog,
  },

  emits: ["open"],

  setup() {
    return {
      store: useDashboardStore(),
    };
  },

  data() {
    return {
      dialog: false,
      editing: null,

      views: [],

      typeFilter: null,
      createdByFilter: null,

      loading: false,
      refreshing: false,
    };
  },

  computed: {
    typeOptions() {
      return [...new Set(this.views.map((v) => v.type))].filter(Boolean);
    },

    createdByOptions() {
      return [...new Set(this.views.map((v) => v.createdBy))].filter(Boolean);
    },

    filteredViews() {
      return this.views.filter((view) => {
        const typeMatch = !this.typeFilter || view.type === this.typeFilter;

        const createdByMatch =
          !this.createdByFilter || view.createdBy === this.createdByFilter;

        return typeMatch && createdByMatch;
      });
    },
  },

  created() {
    this.loadSavedViews();
  },

  methods: {
    async loadSavedViews() {
      this.refreshing = true;

      try {
        const data = await savedViewsApi.getSavedViews();
        this.views = Array.isArray(data) ? data : [];
      } catch (error) {
        console.error("Failed to load saved views:", error);
        toastBus.emit("Failed to load saved views.", "error");
      } finally {
        this.refreshing = false;
      }
    },

    canModify(view) {
      const user = this.store.getUser;

      if (!user) return false;

      const currentUser = `${user.firstName} ${user.lastName}`
        .trim()
        .toLowerCase();

      return (view.createdBy || "").trim().toLowerCase() === currentUser;
    },

    editItem(view) {
      this.editing = {
        ...view,
      };

      this.dialog = true;
    },

    async duplicateItem(view) {
      try {
        await savedViewsApi.duplicateSavedView(view.id);

        await this.loadSavedViews();

        toastBus.emit("View duplicated successfully.", "success");
      } catch (error) {
        console.error(error);

        toastBus.emit("Failed to duplicate saved view.", "error");
      }
    },

    async deleteItem(view) {
      const confirmed = window.confirm(`Delete "${view.name}" ?`);

      if (!confirmed) return;

      try {
        await savedViewsApi.deleteSavedView(view.id);

        await this.loadSavedViews();

        toastBus.emit("View deleted successfully.", "success");
      } catch (error) {
        console.error(error);

        toastBus.emit("Failed to delete saved view.", "error");
      }
    },

    async handleSave(form) {
      const user = this.store.getUser;

      try {
        if (this.editing) {
          await savedViewsApi.updateSavedView(this.editing.id, {
            name: form.name,
            type: form.type,
            desc: form.desc,
          });

          this.editing = null;
        } else {
          await savedViewsApi.createSavedView({
            name: form.name,

            type: form.type || DEFAULT_TYPE,

            desc: form.desc,

            createdBy: user ? `${user.firstName} ${user.lastName}` : "Unknown",
          });
        }

        this.dialog = false;

        await this.loadSavedViews();

        toastBus.emit("View saved successfully.", "success");
      } catch (error) {
        console.error(error);

        toastBus.emit("Failed to save saved view.", "error");
      }
    },
  },
};
</script>

<style scoped>
.sv-wrap {
  padding: 24px;
  background: #f5f7fb;
  min-height: 100%;
  box-sizing: border-box;
}

.sv-card {
  background: #fff;
  border-radius: 14px;
  padding: 24px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
}

/* Header */

.sv-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  gap: 16px;
  flex-wrap: wrap;
}

.sv-title {
  font-size: 22px;
  font-weight: 700;
  color: #1f2937;
}

.sv-sub {
  margin-top: 4px;
  color: #6b7280;
  font-size: 13px;
}

.refresh-btn {
  border-radius: 10px;
}

/* Toolbar */

.toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  flex-wrap: wrap;
  gap: 12px;
}

.toolbar-left {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.filter-select {
  width: 220px;
}

/* Table */

.table-wrapper {
  overflow-x: auto;
}

.saved-table {
  width: 100%;
  min-width: 1050px;
  border-collapse: separate;
  border-spacing: 0 12px;
}

.saved-table thead th {
  background: #f8fafc;
  color: #6b7280;
  text-align: left;
  padding: 14px 16px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  position: sticky;
  top: 0;
  z-index: 2;
}

.saved-table tbody tr {
  background: #fff;
  transition: all 0.25s ease;
}

.saved-table tbody tr:hover {
  transform: translateY(-2px);
}

.saved-table td {
  padding: 18px 16px;
  border-top: 1px solid #edf0f3;
  border-bottom: 1px solid #edf0f3;
  vertical-align: middle;
}

.saved-table td:first-child {
  border-left: 1px solid #edf0f3;
  border-radius: 12px 0 0 12px;
}

.saved-table td:last-child {
  border-right: 1px solid #edf0f3;
  border-radius: 0 12px 12px 0;
}

/* Name */

.view-name {
  color: #1976d2;
  font-weight: 600;
  cursor: pointer;
}

.view-name:hover {
  text-decoration: underline;
}

/* Type */

.type-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  padding: 5px 14px;

  border-radius: 20px;

  background: #e8f1ff;

  color: #1565c0;

  font-size: 12px;

  font-weight: 600;
}

/* Description */

.description {
  max-width: 280px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: #4b5563;
}

/* User */

.creator {
  display: flex;
  align-items: center;
  gap: 10px;
}

.avatar {
  width: 34px;
  height: 34px;

  border-radius: 50%;

  background: #1976d2;

  color: white;

  display: flex;

  align-items: center;

  justify-content: center;

  font-weight: 700;

  font-size: 13px;

  flex-shrink: 0;
}

/* Actions */

.action-buttons {
  display: flex;
  justify-content: flex-end;
  gap: 4px;
}

.action-buttons .v-btn {
  transition: all 0.2s;
}

.action-buttons .v-btn:hover {
  background: rgba(25, 118, 210, 0.08);
}

/* Empty */

.empty-state {
  padding: 50px;
  text-align: center;
  color: #8b8b8b;
}

/* Scrollbar */

.table-wrapper::-webkit-scrollbar {
  height: 8px;
}

.table-wrapper::-webkit-scrollbar-thumb {
  background: #d5d5d5;
  border-radius: 20px;
}

.table-wrapper::-webkit-scrollbar-track {
  background: transparent;
}

/* Responsive */

@media (max-width: 1200px) {
  .saved-table {
    min-width: 980px;
  }
}

@media (max-width: 768px) {
  .sv-wrap {
    padding: 12px;
  }

  .sv-card {
    padding: 16px;
  }

  .toolbar-left {
    width: 100%;
    flex-direction: column;
  }

  .filter-select {
    width: 100%;
  }

  .sv-title {
    font-size: 18px;
  }

  .saved-table {
    min-width: 900px;
  }
}
.sv-table-wrap {
  overflow: auto;
  max-height: calc(100vh - 260px);
}
.sv-table-wrap::-webkit-scrollbar { width: 8px; height: 8px; }
.sv-table-wrap::-webkit-scrollbar-thumb { background: #c7c7c7; border-radius: 4px; }
.sv-table-wrap::-webkit-scrollbar-thumb:hover { background: #999; }

.sv-table th {
  /* ...existing... */
  background: #fff;
  position: sticky;
  top: 0;
  z-index: 2;
}
</style>